{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Human PET imaging showed clear brain uptake of [11C]yohimbine, a basic, moderately lipophilic alkaloid with molecular weight and ionization features similar to the query, supporting meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In vivo mouse pharmacodynamic brain effects (reduced brain GlcCer) demonstrated that a piperidine-containing inhibitor crosses the BBB, directly supporting CNS access for the query's piperidine-based scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "LC-MS analysis in mice showed that AD-8007 reached higher brain levels than a comparator, confirming in vivo brain penetration for a basic amine-containing molecule relevant to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Senicapoc achieved free brain concentrations exceeding free plasma concentrations after oral dosing in rats, demonstrating meaningful CNS access despite multiple aromatic rings and an amide; this supports the query's fluorophenyl ketone and aromatic system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "[18F]FMC, a fluorophenyl ketone with a basic dimethylamino group, showed high initial brain uptake (5.47% ID/g) in mice, providing strong structural analogy for the query's fluorophenyl ketone plus basic amine and indicating good BBB permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A fluorophenyl-containing amide achieved a brain:plasma ratio of 1.29 in mice and was classified as having good brain permeability, supporting the query's ability to achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful CNS access through direct brain uptake, CSF/free brain exposure, brain:plasma ratios, or pharmacodynamic brain effects. These transferable in vivo data override the moderate passive-diffusion/ionization prior, supporting a pass for the query.",
  "evidence_gaps": [
    "No direct Kp,uu or unbound brain-to-plasma ratio data are available for the exact query molecule.",
    "Efflux transporter (P-gp/BCRP) liability is not experimentally excluded for the query.",
    "The basic pKa of 7.84 may reduce the neutral fraction and could lower unbound brain concentrations in vivo.",
    "Human CNS exposure data for the exact query are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

